mapper.select:

WHERE r.customer_id = #{customerId}
    AND so.customer_id = #{customerId}
    AND r.entry_type = 'NORMAL'
    AND r.deleted = FALSE

    AND CASE WHEN GREATEST(r.amount - red.redAmount - written.writtenOffAmount, 0) = 0
        AND GREATEST(written.writtenOffAmount - (r.amount - red.redAmount),
        0) = 0 THEN 'SETTLED' WHEN written.writtenOffAmount = 0 THEN 'OPEN' ELSE 'PARTIAL' END = #{settleState}

ORDER BY r.event_at DESC, r.id DESC


WHERE r.id = #{receivableId}
    AND r.customer_id = #{customerId}
    AND so.customer_id = #{customerId}
    AND r.entry_type = 'NORMAL'
    AND r.deleted = FALSE
